#include <iostream>
using namespace std;

long long binpow(long long a, long long b) {
    long long res = 1;
    while (b > 0) {
        if (b & 1)
            res *= a;
        a *= a;
        b >>= 1;
    }
    return res;
}

int main() {
    long long n;
    cin >> n;

    if (n == 3) {
        cout << 24 << '\n';
        return 0;
    }

    long long ans = 4 * (6 * binpow(4, n - 3) + 9 * binpow(4, n - 4));
    cout << ans << '\n';
    return 0;
}

